/*
 * M2-10: search inside her course material (word search, not meaning search; embeddings are M8-09).
 *
 *   await searchPages(userId, { query: "cell wall", courseId, limit: 8 })
 *     // [{ fileId, fileName, page, snippet }], best match first
 *   await pagesFor(userId, fileId, { from: 3, to: 7, maxChars: 12_000 })
 *     // [{ page, text }], in page order, for building prompts
 *
 * Both read `file_pages`, which M2-09 (`extract.ts`) fills. Its `tsv` column is generated by
 * Postgres as `to_tsvector('simple', text)`, so the query side uses the same 'simple' config:
 * no stemming and no stop words, which suits course text in any language (Finnish, Swedish,
 * English) but means "cells" does not find "cell". The query is read with `websearch_to_tsquery`,
 * so she can type like a search box: `"cell wall"` for a phrase, `or`, `-word` to leave one out.
 * Input it cannot use (only punctuation, say) becomes an empty query, which matches nothing.
 *
 * Ownership. Every call takes the caller's `userId` and only reads pages of `course_files` rows
 * whose `user_id` is that user. Someone else's file id gives `[]`, never an error, so a caller
 * cannot tell another user's file from one that does not exist.
 *
 * Ranking. `ts_rank_cd(tsv, query, 1)`: cover density (how many query words, how close together),
 * divided by 1 + log(page length) so a long page that mentions a word once does not beat a short
 * page about it. Ties break by file name, then file id, then page number, so the same query on the
 * same data always gives the same order (prompts and tests depend on that).
 *
 * Snippets. `ts_headline` with no highlight markers (StartSel and StopSel empty): plain text, no
 * HTML, ready to put into a prompt or show as is. Up to two fragments of 8 to 24 words, joined by
 * " … ". Tags in the page text are dropped by the headline parser; runs of whitespace are folded
 * to one space here. Headlines are only built for the rows that are returned.
 */
import { and, asc, eq, gte, lte, sql } from "drizzle-orm";
import type { Db } from "@/server/db/client";
import { courseFiles, filePages } from "@/server/db/schema/courses";

export const DEFAULT_LIMIT = 8;
export const MAX_LIMIT = 50;

export type SearchHit = {
  fileId: string;
  fileName: string;
  page: number;
  snippet: string;
};

export type SearchOptions = {
  query: string;
  /** Only this course. Leave out to search all her courses. */
  courseId?: string;
  /** How many hits. Default 8, at most 50; anything below 1 counts as 1. */
  limit?: number;
  /** For tests. Defaults to the app database. */
  db?: Db;
};

export type PageText = { page: number; text: string };

export type PagesOptions = {
  /** First page to include (1-based). Default: the first page. */
  from?: number;
  /** Last page to include. Default: the last page. */
  to?: number;
  /**
   * Most characters of page text to return (page text only, nothing for separators). Pages are
   * taken whole, in order, and it stops before the first page that would go over. Only when the
   * first page alone is over the limit is that one page cut to `maxChars`, so the answer is
   * never empty just because a page is long. Leave out for no limit.
   */
  maxChars?: number;
  /** For tests. Defaults to the app database. */
  db?: Db;
};

const HEADLINE_OPTIONS =
  'StartSel="", StopSel="", MaxWords=24, MinWords=8, ShortWord=2, MaxFragments=2, FragmentDelimiter=" … "';

async function appDb(db?: Db): Promise<Db> {
  return db ?? (await import("@/server/db/client")).db;
}

function clampLimit(limit: number | undefined): number {
  if (limit === undefined || !Number.isFinite(limit)) return DEFAULT_LIMIT;
  return Math.min(MAX_LIMIT, Math.max(1, Math.floor(limit)));
}

/** Her pages that match `query`, best first. Empty or blank query gives `[]`. */
export async function searchPages(userId: string, options: SearchOptions): Promise<SearchHit[]> {
  const text = options.query.trim();
  if (!text) return [];
  const db = await appDb(options.db);
  const limit = clampLimit(options.limit);

  const tsq = sql`websearch_to_tsquery('simple', ${text})`;
  const rank = sql<number>`ts_rank_cd(${filePages.tsv}, ${tsq}, 1)`;
  const where = and(
    eq(courseFiles.userId, userId),
    options.courseId ? eq(courseFiles.courseId, options.courseId) : undefined,
    sql`${filePages.tsv} @@ ${tsq}`,
  );

  // Rank and cut first, then build headlines only for the rows we keep.
  const top = db
    .select({
      fileId: filePages.fileId,
      fileName: sql<string>`${courseFiles.name}`.as("file_name"),
      page: filePages.page,
      body: sql<string>`${filePages.text}`.as("body"),
      rank: rank.as("rank"),
    })
    .from(filePages)
    .innerJoin(courseFiles, eq(courseFiles.id, filePages.fileId))
    .where(where)
    .orderBy(sql`${rank} desc`, asc(courseFiles.name), asc(filePages.fileId), asc(filePages.page))
    .limit(limit)
    .as("top");

  const rows = await db
    .select({
      fileId: top.fileId,
      fileName: top.fileName,
      page: top.page,
      snippet: sql<string>`ts_headline('simple', ${top.body}, ${tsq}, ${HEADLINE_OPTIONS})`,
    })
    .from(top)
    .orderBy(sql`${top.rank} desc`, asc(top.fileName), asc(top.fileId), asc(top.page));

  return rows.map((r) => ({ ...r, snippet: r.snippet.replace(/\s+/g, " ").trim() }));
}

/** Text of her file's pages, in page order. Someone else's (or no such) file gives `[]`. */
export async function pagesFor(
  userId: string,
  fileId: string,
  options: PagesOptions = {},
): Promise<PageText[]> {
  const db = await appDb(options.db);
  const rows = await db
    .select({ page: filePages.page, text: filePages.text })
    .from(filePages)
    .innerJoin(courseFiles, eq(courseFiles.id, filePages.fileId))
    .where(
      and(
        eq(filePages.fileId, fileId),
        eq(courseFiles.userId, userId),
        options.from !== undefined ? gte(filePages.page, options.from) : undefined,
        options.to !== undefined ? lte(filePages.page, options.to) : undefined,
      ),
    )
    .orderBy(asc(filePages.page));

  const max = options.maxChars;
  if (max === undefined) return rows;
  const budget = Math.max(0, Math.floor(max));

  const out: PageText[] = [];
  let used = 0;
  for (const row of rows) {
    if (used + row.text.length > budget) {
      if (out.length === 0 && budget > 0) out.push({ page: row.page, text: row.text.slice(0, budget) });
      break;
    }
    out.push(row);
    used += row.text.length;
  }
  return out;
}
